create table if not exists public.auth_login_attempts (login_key text primary key, failure_count integer not null default 0, first_failed_at timestamptz, last_failed_at timestamptz, blocked_until timestamptz, updated_at timestamptz not null default now()); alter table public.auth_login_attempts enable row level security; drop policy if exists northlight_pilot_backend on public.auth_login_attempts; create policy northlight_pilot_backend on public.auth_login_attempts for all to anon, authenticated using (public.northlight_pilot_allowed()) with check (public.northlight_pilot_allowed());